def heat_wait(readings):
    size = len(readings)
    waiting = []
    delays = []
    for i in range(size):
        delays.append(0)
    for tick in range(2 * size):
        i = tick % size
        while len(waiting) > 0 and readings[waiting[-1]] < readings[i]:
            old = waiting.pop()
            delays[old] = tick - old
        if tick < size:
            waiting.append(i)
    return delays

